/* ParksMap — the 3D relief map of the lower 48 with every national park on it.
 *
 * Everything drawn is real data, generated by tools/build-parks.mjs:
 *   - the ground is an elevation grid (src/data/usRelief.js), coloured in flat
 *     screenprint bands like a 1930s park poster
 *   - each light stands on a park's own National Park Service coordinate
 * ONE projection (`project`) places the ground and every light. lat first.
 *
 * The canvas is transparent: the dusk sky behind it is CSS (ParksMapPage.css).
 * The canvas is a view, not the only way in: the page's index reaches every park with
 * a 44px target and a keyboard, and carries the parks that sit off this canvas.
 */
import React, { useEffect, useMemo, useRef, useState } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import { OrbitControls, Html } from '@react-three/drei'
import * as THREE from 'three'
import { RELIEF } from './data/usRelief'

const W = 100
const { bounds, cols, rows } = RELIEF
const MID_LAT = (bounds.north + bounds.south) / 2
const ASPECT =
  ((bounds.east - bounds.west) * Math.cos((MID_LAT * Math.PI) / 180)) /
  (bounds.north - bounds.south)
const D = W / ASPECT
const RISE = 3.6 // world units at maxMetres: exaggerated so relief reads at continental scale
const BANDS = 13 // flat elevation bands, like poster ink layers

const bytes = (b64) => Uint8Array.from(window.atob(b64), (c) => c.charCodeAt(0))
const HEIGHT = bytes(RELIEF.height)
const KIND = bytes(RELIEF.kind)

export function inCanvas(park) {
  return (
    park.lng > bounds.west &&
    park.lng < bounds.east &&
    park.lat > bounds.south &&
    park.lat < bounds.north
  )
}

/** lat first. Returns [x, z] on the ground plane. */
export function project(lat, lng) {
  const x = ((lng - bounds.west) / (bounds.east - bounds.west)) * W - W / 2
  const z = ((bounds.north - lat) / (bounds.north - bounds.south)) * D - D / 2
  return [x, z]
}

function groundAt(lat, lng) {
  const c = Math.round(((lng - bounds.west) / (bounds.east - bounds.west)) * (cols - 1))
  const r = Math.round(((bounds.north - lat) / (bounds.north - bounds.south)) * (rows - 1))
  const i = Math.max(0, Math.min(rows - 1, r)) * cols + Math.max(0, Math.min(cols - 1, c))
  return (HEIGHT[i] / 255) * RISE
}

/* Dusk Field Guide palette, exclusive to /outdoors. */
const INK = [
  [0.0, '#24402F'],
  [0.06, '#35573B'],
  [0.14, '#5C7A4E'],
  [0.26, '#8C8A55'],
  [0.4, '#A9744A'],
  [0.56, '#C08A5A'],
  [0.74, '#D9BF95'],
  [1.0, '#F1E8D4'],
].map(([t, hex]) => [t, new THREE.Color(hex)])
const WATER = new THREE.Color('#12202B')
const ABROAD_LOW = new THREE.Color('#17231E')
const ABROAD_HIGH = new THREE.Color('#26342D')
const EMBER = '#F2B45A'
const HOT = '#FFF1D0'

function ink(t, out) {
  const q = Math.min(1, Math.round(t * BANDS) / BANDS)
  for (let i = 1; i < INK.length; i++) {
    if (q <= INK[i][0]) {
      const [t0, c0] = INK[i - 1]
      const [t1, c1] = INK[i]
      return out.copy(c0).lerp(c1, (q - t0) / (t1 - t0))
    }
  }
  return out.copy(INK[INK.length - 1][1])
}

function useTerrain() {
  return useMemo(() => {
    const pos = new Float32Array(cols * rows * 3)
    const col = new Float32Array(cols * rows * 3)
    const tmp = new THREE.Color()
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const i = r * cols + c
        const t = HEIGHT[i] / 255
        pos[i * 3] = (c / (cols - 1)) * W - W / 2
        pos[i * 3 + 1] = KIND[i] === 0 ? -0.08 : t * RISE
        pos[i * 3 + 2] = (r / (rows - 1)) * D - D / 2
        if (KIND[i] === 0) tmp.copy(WATER)
        else if (KIND[i] === 1) ink(t, tmp)
        else tmp.copy(ABROAD_LOW).lerp(ABROAD_HIGH, Math.min(1, t * 2.2))
        col[i * 3] = tmp.r
        col[i * 3 + 1] = tmp.g
        col[i * 3 + 2] = tmp.b
      }
    }
    const idx = new Uint32Array((cols - 1) * (rows - 1) * 6)
    let k = 0
    for (let r = 0; r < rows - 1; r++) {
      for (let c = 0; c < cols - 1; c++) {
        const a = r * cols + c
        const b = a + 1
        const d = a + cols
        const e = d + 1
        // Only the United States is drawn: the country is a cut-out standing in the dusk.
        if (KIND[a] !== 1 && KIND[b] !== 1 && KIND[d] !== 1 && KIND[e] !== 1) continue
        idx[k++] = a
        idx[k++] = d
        idx[k++] = b
        idx[k++] = b
        idx[k++] = d
        idx[k++] = e
      }
    }
    const g = new THREE.BufferGeometry()
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    g.setAttribute('color', new THREE.BufferAttribute(col, 3))
    g.setIndex(new THREE.BufferAttribute(idx.subarray(0, k), 1))
    g.computeVertexNormals()
    return g
  }, [])
}

function Terrain({ still }) {
  const geometry = useTerrain()
  const ref = useRef()
  const t0 = useRef(null)
  useFrame(({ clock }) => {
    if (!ref.current || still) return
    if (t0.current === null) t0.current = clock.elapsedTime
    const p = Math.min(1, (clock.elapsedTime - t0.current) / 2)
    ref.current.scale.y = 0.02 + 0.98 * (1 - Math.pow(1 - p, 3)) // the land rises, once
  })
  return (
    <mesh ref={ref} geometry={geometry} scale={[1, still ? 1 : 0.02, 1]}>
      <meshStandardMaterial vertexColors roughness={1} metalness={0} />
    </mesh>
  )
}

function useGlowTexture() {
  return useMemo(() => {
    const c = document.createElement('canvas')
    c.width = c.height = 128
    const g = c.getContext('2d')
    const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64)
    grad.addColorStop(0, 'rgba(255,241,208,1)')
    grad.addColorStop(0.18, 'rgba(242,180,90,0.85)')
    grad.addColorStop(0.5, 'rgba(217,151,59,0.22)')
    grad.addColorStop(1, 'rgba(217,151,59,0)')
    g.fillStyle = grad
    g.fillRect(0, 0, 128, 128)
    const t = new THREE.CanvasTexture(c)
    t.colorSpace = THREE.SRGBColorSpace
    return t
  }, [])
}

/* A park is a lit campfire seen from far off: a hot point, a soft glow, a thin thread of light. */
function Light({ park, index, active, hovered, still, glow }) {
  const [x, z] = project(park.lat, park.lng)
  const y = groundAt(park.lat, park.lng)
  const group = useRef()
  const halo = useRef()
  const t0 = useRef(null)
  useFrame(({ clock }) => {
    if (!group.current) return
    let s = 1
    if (!still) {
      if (t0.current === null) t0.current = clock.elapsedTime
      const p = Math.min(
        1,
        Math.max(0, (clock.elapsedTime - t0.current - 1.5 - index * 0.03) / 0.6)
      )
      s = 1 - Math.pow(1 - p, 3)
    }
    group.current.visible = s > 0.001
    group.current.scale.setScalar(Math.max(0.001, s))
    if (halo.current) {
      const base = active ? 5.2 : hovered ? 3.6 : 2.3
      const breathe = still ? 0 : Math.sin(clock.elapsedTime * 1.4 + index) * 0.12
      const cur = halo.current.scale.x
      halo.current.scale.setScalar(cur + (base * (1 + breathe) - cur) * 0.15)
    }
  })
  const reach = active ? 4.6 : hovered ? 3 : 1.7
  return (
    <group position={[x, y, z]}>
      <group ref={group}>
        <mesh position={[0, reach / 2, 0]}>
          <cylinderGeometry args={[0.018, 0.05, reach, 6, 1, true]} />
          <meshBasicMaterial
            color={active ? HOT : EMBER}
            transparent
            opacity={active ? 0.9 : 0.55}
            depthWrite={false}
            blending={THREE.AdditiveBlending}
          />
        </mesh>
        <sprite ref={halo} position={[0, 0.25, 0]} scale={[2.3, 2.3, 1]}>
          <spriteMaterial
            map={glow}
            transparent
            depthWrite={false}
            blending={THREE.AdditiveBlending}
          />
        </sprite>
        <mesh position={[0, 0.16, 0]}>
          <sphereGeometry args={[active ? 0.3 : 0.2, 12, 10]} />
          <meshBasicMaterial color={HOT} />
        </mesh>
      </group>
      {(hovered || active) && (
        <Html
          position={[0, reach + 0.7, 0]}
          center
          zIndexRange={[20, 0]}
          style={{ pointerEvents: 'none' }}
        >
          <span className={`parksmap-label${active ? ' is-active' : ''}`}>{shortName(park)}</span>
        </Html>
      )}
    </group>
  )
}

export function shortName(park) {
  return park.name.replace(/ National Parks?( (&|and) Preserve)?$| National and State Parks$/, '')
}

const HOME_DIR = new THREE.Vector3(0, 0.74, 0.67).normalize()
/** The home view. On a wide screen the country sits right of the title; on a tall one, under it. */
function homeView(camera, size) {
  const half = Math.tan((camera.fov * Math.PI) / 360)
  const aspect = size.width / size.height
  const wide = aspect > 1.25
  const share = wide ? 0.7 : 0.96 // how much of the width the country may take
  const dist = Math.max(W / (2 * half * aspect * share), (D * 1.45) / (2 * half))
  const visibleW = 2 * half * aspect * dist
  return { dist, x: wide ? -visibleW * 0.13 : 0, z: -dist * (wide ? 0.07 : 0.2) }
}

function Rig({ focus, still, coarse }) {
  const controls = useRef()
  const { camera, size } = useThree()
  const want = useRef({
    target: new THREE.Vector3(),
    offset: new THREE.Vector3(),
    moving: true,
    first: true,
  })
  useEffect(() => {
    const w = want.current
    if (focus) {
      const [x, z] = project(focus.lat, focus.lng)
      w.target.set(x, groundAt(focus.lat, focus.lng), z)
      w.offset.set(0, 24, 23)
    } else {
      const home = homeView(camera, size)
      w.target.set(home.x, 0, home.z)
      w.offset.copy(HOME_DIR).multiplyScalar(home.dist)
    }
    w.moving = true
  }, [focus, camera, size])
  useFrame(() => {
    const c = controls.current
    if (!c) return
    const w = want.current
    if (w.moving) {
      const k = still || w.first ? 1 : 0.065
      w.first = false
      c.target.lerp(w.target, k)
      const goal = w.target.clone().add(w.offset)
      camera.position.lerp(goal, k)
      if (camera.position.distanceTo(goal) < 0.05) w.moving = false
    }
    c.update()
  })
  return (
    <OrbitControls
      ref={controls}
      enabled={!coarse}
      enablePan={false}
      enableZoom={false} /* the page must keep its scroll wheel */
      enableDamping
      dampingFactor={0.08}
      minPolarAngle={0.35}
      maxPolarAngle={1.12}
      minAzimuthAngle={-0.6}
      maxAzimuthAngle={0.6}
      onStart={() => {
        want.current.moving = false
      }}
    />
  )
}

/* One picker for the whole canvas: the light nearest the pointer in SCREEN space wins.
 * Per-light hit meshes failed where parks cluster (a click on Yellowstone chose Grand
 * Teton, whose target stood in front of it). A drag never selects. */
function Picker({ parks, onHover, onSelect }) {
  const { camera, gl, size } = useThree()
  useEffect(() => {
    const el = gl.domElement
    const v = new THREE.Vector3()
    const nearest = (e) => {
      const r = el.getBoundingClientRect()
      const px = e.clientX - r.left
      const py = e.clientY - r.top
      let best = null
      let bestD = 30
      for (const p of parks) {
        const [x, z] = project(p.lat, p.lng)
        const g = groundAt(p.lat, p.lng)
        for (const lift of [0.2, 1, 1.8]) {
          v.set(x, g + lift, z).project(camera)
          const d = Math.hypot(
            ((v.x + 1) / 2) * size.width - px,
            ((1 - v.y) / 2) * size.height - py
          )
          if (d < bestD) {
            bestD = d
            best = p.code
          }
        }
      }
      return best
    }
    let down = null
    const move = (e) => onHover(e.pointerType === 'touch' ? null : nearest(e))
    const leave = () => onHover(null)
    const press = (e) => {
      down = [e.clientX, e.clientY]
    }
    const release = (e) => {
      if (!down) return
      const dragged = Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 6
      down = null
      if (dragged) return
      const hit = nearest(e)
      if (hit) onSelect(hit)
    }
    el.addEventListener('pointermove', move)
    el.addEventListener('pointerleave', leave)
    el.addEventListener('pointerdown', press)
    el.addEventListener('pointerup', release)
    return () => {
      el.removeEventListener('pointermove', move)
      el.removeEventListener('pointerleave', leave)
      el.removeEventListener('pointerdown', press)
      el.removeEventListener('pointerup', release)
    }
  }, [camera, gl, size, parks, onHover, onSelect])
  return null
}

/* ?debug exposes each light's screen position so a browser test can click the real thing. */
function DebugProbe({ parks }) {
  const { camera, size } = useThree()
  useEffect(() => {
    if (!/[?&]debug\b/.test(window.location.search)) return undefined
    window.__parksScreen = (code) => {
      const p = parks.find((q) => q.code === code)
      if (!p) return null
      const [x, z] = project(p.lat, p.lng)
      const v = new THREE.Vector3(x, groundAt(p.lat, p.lng) + 0.2, z).project(camera)
      return { x: ((v.x + 1) / 2) * size.width, y: ((1 - v.y) / 2) * size.height }
    }
    return () => {
      delete window.__parksScreen
    }
  }, [camera, size, parks])
  return null
}

function Lights({ parks, selected, hover, still }) {
  const glow = useGlowTexture()
  return parks.map((p, i) => (
    <Light
      key={p.code}
      park={p}
      index={i}
      active={p.code === selected}
      hovered={p.code === hover}
      still={still}
      glow={glow}
    />
  ))
}

function canWebGL() {
  try {
    const c = document.createElement('canvas')
    return !!(c.getContext('webgl2') || c.getContext('webgl'))
  } catch {
    return false
  }
}

export default function ParksMap({ parks, selected, onSelect }) {
  const [hover, setHover] = useState(null)
  const [ok] = useState(canWebGL)
  const still = useMemo(
    () =>
      typeof window !== 'undefined' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  )
  const coarse = useMemo(
    () => typeof window !== 'undefined' && window.matchMedia('(pointer: coarse)').matches,
    []
  )
  const onMap = useMemo(() => parks.filter(inCanvas), [parks])
  const focus = onMap.find((p) => p.code === selected) || null

  if (!ok) {
    return (
      <div className="parksmap parksmap--flat" role="note">
        This device can&rsquo;t draw the 3D map. Every park is in the index below.
      </div>
    )
  }
  return (
    <div className={`parksmap${hover ? ' is-hovering' : ''}`}>
      <Canvas
        dpr={[1, 1.75]}
        camera={{ fov: 32, near: 1, far: 1200, position: [0, 90, 82] }}
        gl={{ antialias: true, alpha: true, powerPreference: 'high-performance' }}
        aria-label="Relief map of the lower 48 states with a light on every national park. The index below the map reaches every park."
        role="img"
      >
        <hemisphereLight args={['#b8c6d6', '#0F1714', 0.62]} />
        {/* last light, low in the west */}
        <directionalLight position={[-80, 30, -8]} intensity={2.9} color="#FFC98A" />
        <directionalLight position={[50, 40, 40]} intensity={0.3} color="#7FB4C9" />
        <Terrain still={still} />
        <Lights parks={onMap} selected={selected} hover={hover} still={still} />
        <Rig focus={focus} still={still} coarse={coarse} />
        <Picker parks={onMap} onHover={setHover} onSelect={onSelect} />
        <DebugProbe parks={onMap} />
      </Canvas>
    </div>
  )
}
